package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="society_incidents") @Data @Builder @NoArgsConstructor @AllArgsConstructor
public class SocietyIncident {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account; @Column(nullable=false,length=30) private String incidentNumber; @Column(nullable=false,length=180) private String title; @Column(nullable=false,length=2000) private String description; @Column(nullable=false,length=20) private String severity; private String location; @Column(nullable=false) private LocalDateTime occurredAt; @Column(nullable=false,length=20) @Builder.Default private String status="OPEN"; @Column(length=2000) private String immediateAction; @Column(length=2000) private String followUp; @Column(nullable=false) @Builder.Default private Boolean sensitive=false; private LocalDateTime closedAt; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by_user_id",nullable=false) private User createdBy; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="closed_by_user_id") private User closedBy; @Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime createdAt=LocalDateTime.now(); @Column(nullable=false) @Builder.Default private LocalDateTime updatedAt=LocalDateTime.now(); @PreUpdate void touch(){updatedAt=LocalDateTime.now();}}
